(()=>{const cats=[['shoes','Shoes','shoes'],['hoodies','Hoodies','hoodies-sweaters'],['jackets','Jackets','jackets'],['pants','Pants & Shorts','pants-shorts'],['hats','Headwear','headwear'],['socks','Socks',null],['electronics','Electronics','electronics'],['watches','Watches',null],['belts','Belts',null],['slippers','Slippers & Slides',null],['t-shirts','T-Shirts','t-shirts'],['sets','Short Sets','ShortSets'],['jersey','Jersey','jersey'],['accessories','Accessories','accessories'],['other','Other Finds','other-stuff']];const re={socks:/\bsocks?\b/i,watches:/\bwatch(?:es)?\b/i,belts:/\bbelts?\b/i,slippers:/\b(slippers?|slides?|sandals?)\b/i};const positions={"shoes":[0,0],"hoodies":[25,0],"jackets":[50,0],"pants":[75,0],"hats":[100,0],"socks":[0,50],"electronics":[25,50],"watches":[50,50],"belts":[75,50],"slippers":[100,50],"t-shirts":[0,100],"sets":[25,100],"jersey":[50,100],"accessories":[75,100],"other":[100,100]};const art=k=>`<span class="category-art" style="--cx:${positions[k][0]}%;--cy:${positions[k][1]}%" aria-hidden="true"></span>`;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const matches=(p,c)=>!c|| (c[2]?p.category===c[2]:re[c[0]].test(p.name));const categoryQueries={shoes:['鞋','鞋子','运动鞋','schuhe','chaussures','zapatos','scarpe','sapatos','schoenen','buty','skor'],hoodies:['连帽衫','卫衣','kapuzenpullover','sudaderas','felpe','moletom','hoodies','bluzy','huvtröjor'],jackets:['夹克','外套','jacken','vestes','chaquetas','giacche','jaquetas','jassen','kurtki','jackor'],pants:['裤子','短裤','hosen','pantalons','pantalones','pantaloni','calças','broeken','spodnie','byxor'],hats:['帽子','kopfbedeckungen','gorras','cappelli','bonés','petten','czapki','huvudbonader'],socks:['袜子','袜','socken','chaussettes','calcetines','calze','meias','sokken','skarpety','strumpor'],electronics:['电子产品','电子','elektronik','électronique','electrónica','elettronica','eletrônicos','elektronika'],watches:['手表','腕表','uhren','montres','relojes','orologi','relógios','horloges','zegarki','klockor'],belts:['腰带','皮带','gürtel','ceintures','cinturones','cinture','cintos','riemen','paski','bälten'],slippers:['拖鞋','凉拖','hausschuhe','chaussons','pantuflas','pantofole','pantufas','slippers','kapcie','tofflor'], 't-shirts':['t恤','t恤衫','t-shirts','camisetas','magliette','koszulki','t-shirtar'],sets:['短套装','套装','sets','ensembles','conjuntos','completi','zestawy','shortsset'],jersey:['球衣','trikots','maillots','camisetas deportivas','maglie','camisas esportivas','stroje','matchtröjor'],accessories:['配饰','饰品','accessoires','accessori','accesorios','acessórios','accessoarer','akcesoria'],other:['其他好物','其他','weitere artikel','autres articles','otros artículos','altri articoli','outros artigos','overige vondsten','pozostałe','övriga fynd']};const normalizeSearch=v=>String(v??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase().replace(/\s+/g,' ').trim();const queryMatches=(p,q)=>{if(!q)return true;const term=normalizeSearch(q);if(normalizeSearch(`${p.name} ${p.category} ${p.id} ${p.weidianId}`).includes(term))return true;if(window.joyagooProductSearch?.(p.name,q))return true;return cats.some(c=>(normalizeSearch(c[1])===term||(categoryQueries[c[0]]||[]).some(x=>normalizeSearch(x)===term))&&matches(p,c))};const usd=v=>Number.isFinite(Number(v))&&String(v).trim()?'$'+(Number(v)/6.6753).toFixed(2)+' USD':'Price unavailable';const url=p=>'https://joyagoo.com/product?id='+encodeURIComponent(p.weidianId)+'&platform=WEIDIAN&productUrl=&productPwd=';let products=[],selected=location.pathname.split('/').filter(Boolean)[0]==='categories'?(location.pathname.split('/').filter(Boolean)[1]||''):'',page=1,query=new URLSearchParams(location.search).get('q')||'';const side=document.querySelector('#browse-categories'),grid=document.querySelector('#browse-products'),status=document.querySelector('#browse-status'),title=document.querySelector('#browse-title'),sort=document.querySelector('#browse-sort'),input=document.querySelector('#search-input');input.value=query;grid.addEventListener('error',e=>{const img=e.target;if(img.tagName==='IMG'&&img.dataset.fallback){const fallback=img.dataset.fallback;delete img.dataset.fallback;img.src=fallback}},true);function updateAddress(){const path=selected?'/categories/'+encodeURIComponent(selected)+'/':'/catalog/';const params=new URLSearchParams();if(query.trim())params.set('q',query.trim());const next=path+(params.size?'?'+params.toString():'');if(location.pathname+location.search!==next)history.pushState({},'',next)}function activate(id,scroll){if(id){query='';input.value=''}selected=id;page=1;updateAddress();render();if(scroll)document.querySelector('#browse').scrollIntoView({behavior:'smooth'})}window.addEventListener('popstate',()=>{const parts=location.pathname.split('/').filter(Boolean);selected=parts[0]==='categories'?(parts[1]||''):'';query=new URLSearchParams(location.search).get('q')||'';input.value=query;page=1;render()});function sideRender(){side.innerHTML=[['','All products'],...cats.map(c=>[c[0],c[1]])].map(([id,name])=>`<button type="button" data-cat="${esc(id)}" class="${id===selected?'is-active':''}" aria-pressed="${id===selected}">${esc(name)} <span>↗</span></button>`).join('');side.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>activate(b.dataset.cat,false)))}function render(){sideRender();const cat=cats.find(c=>c[0]===selected);title.textContent=cat?cat[1]:'All products';const q=query.trim().toLowerCase();let arr=products.filter(p=>matches(p,cat)&&queryMatches(p,q));if(sort.value==='low')arr.sort((a,b)=>Number(a.price)-Number(b.price));else if(sort.value==='high')arr.sort((a,b)=>Number(b.price)-Number(a.price));else arr.sort((a,b)=>Number(b.id)-Number(a.id));const total=Math.max(1,Math.ceil(arr.length/24));page=Math.min(total,page);status.textContent=`${arr.length.toLocaleString()} products · Page ${page} of ${total}`;grid.innerHTML=arr.slice((page-1)*24,page*24).map(p=>`<article class="product-card" data-weidian-id="${esc(p.weidianId)}"><a href="/product/?id=${encodeURIComponent(p.id)}"><div class="product-image"><img loading="lazy" src="${esc(p.image)}" data-fallback="${esc((p.weidianImages||[]).find(x=>/^https:\/\//.test(x)&&x!==p.image)||'')}" alt="${esc(p.name)}"></div><div class="product-info"><small>${esc(p.category)}</small><h3>${esc(p.name)}</h3><div class="product-bottom"><span data-cny-price="${esc(p.price)}">${usd(p.price)}</span><b>View details ↗</b></div></div></a></article>`).join('')||'<p>No matching products found.</p>';document.querySelector('#browse-prev').disabled=page===1;document.querySelector('#browse-next').disabled=page===total}
document.querySelector('#hero-search').addEventListener('submit',e=>{e.preventDefault();query=input.value;activate('',true)});sort.addEventListener('change',()=>{page=1;render()});document.querySelector('#browse-prev').onclick=()=>{page--;render();document.querySelector('#browse').scrollIntoView()};document.querySelector('#browse-next').onclick=()=>{page++;render();document.querySelector('#browse').scrollIntoView()};fetch('/catalog.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{products=d.products.filter(p=>p.id!=='6250'&&/^\d+$/.test(String(p.weidianId||''))&&p.image);render()}).catch(()=>{status.textContent='Unable to load the product catalogue.'})})();
